"use strict";(globalThis.webpackChunkgrc||=[]).push([[78708],{33266(e){e.exports=JSON.parse('{"citeKey":"sun2001adaptivemultivariate","slug":"sun-2001-adaptive-multivariate-7894","title":"Adaptive Multivariate Regression for Advanced Memory System Evaluation: Application and Experience","authors":["X.-H. Sun","D. He","K. Cameron","Y. Luo"],"venue":"Journal of Performance Evaluation, Volume 45, Issue 1, May 2001, Pages 1-18","type":"Journal","entryType":"article","date":"May, 2001","year":2001,"era":"iit","month":5,"doi":"10.1016/s0166-5316(00)00051-1","abstract":"Recent advances in latency hiding techniques have made performance evaluation of memory hierarchies a more difficult task. Applications compiled for a particular architecture may be executed on vastly different memory hierarchy implemen- tations. There is a need for performance analysis techniques that provide methods for understanding the interaction between applications and a given memory hierarchy. In this paper, we present a statistical approach to performance analysis of ad- vanced memory hierarchy implementations. The method involves the utilization of previously available statistical analysis techniques coupled with scalability analysis. The result is a novel step-wise approach to understanding the hierarchical mem- ory performance of scientific applications. We apply the method to several scientific applications of interest to the accelerated strategic computing initiative (ASCI) over the SGI machines PowerChallenge and Origin 2000. Results indicate some codes are statistically identical in memory performance, while others vary greatly. Furthermore, some codes do not take advantage of the performance enhancements to the memory system found in the Origin 2000.","hasAbstract":true,"lede":"We present a statistical approach to performance analysis of ad- vanced memory hierarchy implementations.","links":{"pdf":"https://grc.iit.edu/papers/2001/sun-2001-adaptive-multivariate-7894.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);